import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let real numbers x_1 \\le x_2 \\le \\cdots \\le x_{alpha} satisfy \\sum_{i=1}^{alpha} x_i = 1, where alpha is an odd integer. Let m = (alpha+1)/2. Determine the exact maximum value of\n\n((\\sum_{i=1}^{alpha} |x_i - x_m|)^2 * \\sum_{1 \\le i < j \\le alpha} (x_i - x_j)^2) / (\\sum_{i=1}^{alpha} x_i^2)^3.\n\nYour answer should be a closed-form expression in terms of alpha.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose alpha as an odd multiple of 9 to make the closed-form maximum an integer
# Keep sizes moderate to avoid numerical issues in any auxiliary checks
choices = [9, 27, 45, 63]
alpha = rng.choice(choices)
return {'alpha': int(alpha)}

    def verifier(assign):
# Verify domain and compute the maximum as a function of alpha
# Also construct an extremizing configuration to sanity-check the value numerically
alpha = assign.get('alpha', None)
if not isinstance(alpha, int):
    # alpha must be an integer
    return (False, None)  # invalid assignment: alpha not int
if alpha < 5 or alpha % 2 == 0:
    # needs odd alpha >= 5
    return (False, None)
if alpha % 9 != 0:
    # For this family we ensure integer answer; generator always satisfies this
    return (False, None)
# Closed-form maximum derived in notes: M(alpha) = 4 * alpha^2 * (alpha - 1) / 27
# Since alpha is a multiple of 9, this is an integer.
answer = (4 * (alpha ** 2) * (alpha - 1)) // 27

# Optional sanity check by constructing an extremal sequence:
# For n = alpha = 2p+1, the extremizer is
# x_1=...=x_p = 1/n - 1/sqrt(n p), x_{p+1} = 1/n, x_{p+2}=...=x_n = 1/n + 1/sqrt(n p)
# This achieves the maximum.
import math
n = alpha
p = (n - 1) // 2
t = 1.0 / n
u = 1.0 / math.sqrt(n * p)
a = t - u
b = t + u
xs = [a] * p + [t] + [b] * p
# Compute the expression
S = sum(xs)
if abs(S - 1.0) > 1e-9 or any(xs[i] > xs[i+1] for i in range(n-1)):
    return (False, None)  # ordering or sum violated (should not happen)
# Sums needed
sum_abs = sum(abs(x - xs[p]) for x in xs)  # xs[p] is the median x_m
sum_sq = sum(x*x for x in xs)
# Pairwise sum of squares identity
pair = n * sum_sq - S * S
val = (sum_abs ** 2) * pair / (sum_sq ** 3)
# Compare with theoretical answer
if not (abs(val - float(answer)) <= 1e-6 * max(1.0, float(answer))):
    # The constructed extremal value should match the closed-form answer within tolerance
    return (False, None)
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

